/**
 * Express REST API Routes for Notes and Real-Time Semantic Organization
 */
import express from 'express';
import { StorageService } from '../services/storage.js';
import { SemanticEngine } from '../services/semanticEngine.js';

const router = express.Router();

// GET all notes
router.get('/notes', (req, res) => {
  try {
    const { category, tag, search } = req.query;
    const notes = StorageService.getAllNotes({ category, tag, search });
    res.json({ success: true, count: notes.length, data: notes });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// GET single note by ID
router.get('/notes/:id', (req, res) => {
  try {
    const note = StorageService.getNoteById(req.params.id);
    if (!note) {
      return res.status(404).json({ success: false, message: 'Note not found' });
    }
    res.json({ success: true, data: note });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// POST create note with auto-classification
router.post('/notes', (req, res) => {
  try {
    const { title, content, category, tags, relationships } = req.body;
    if (!title || !content) {
      return res.status(400).json({ success: false, message: 'Title and content are required' });
    }

    const note = StorageService.createNote({
      title,
      content,
      category,
      tags,
      relationships
    });

    res.status(201).json({ success: true, data: note });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// PUT update note (supports accepting/editing semantic suggestions)
router.put('/notes/:id', (req, res) => {
  try {
    const updated = StorageService.updateNote(req.params.id, req.body);
    if (!updated) {
      return res.status(404).json({ success: false, message: 'Note not found' });
    }
    res.json({ success: true, data: updated });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// DELETE note
router.delete('/notes/:id', (req, res) => {
  try {
    const deleted = StorageService.deleteNote(req.params.id);
    if (!deleted) {
      return res.status(404).json({ success: false, message: 'Note not found' });
    }
    res.json({ success: true, message: 'Note deleted successfully' });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// POST real-time semantic analysis preview (as user types in editor)
router.post('/semantic/analyze', (req, res) => {
  try {
    const { title = '', content = '', category = null, tags = [], targetNoteId = null } = req.body;
    const allNotes = StorageService.getAllNotes();

    const analysis = SemanticEngine.analyzeNote(
      { title, content, category, tags },
      allNotes,
      targetNoteId
    );

    res.json({ success: true, analysis });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// POST seed sample data
router.post('/semantic/seed', (req, res) => {
  try {
    const notes = StorageService.resetAndSeed();
    res.json({ success: true, message: 'Sample dataset loaded successfully', data: notes });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// POST clear all notes
router.post('/semantic/clear', (req, res) => {
  try {
    const notes = StorageService.clearAll();
    res.json({ success: true, message: 'Workspace cleared', data: notes });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

export default router;

