} from 'lucide-react';

export function NoteCard({ note, onSelect, onEdit, onDelete, isSelected }) {
  const categoryValue = note.category?.value || 'General';
  const categorySource = note.category?.source || 'auto';
  const categoryConfidence = note.category?.confidence ? Math.round(note.category.confidence * 100) : 75;
  const relationshipsCount = note.relationships?.length || 0;

  // Format date
  const dateStr = note.createdAt 
    ? new Date(note.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    : 'Recently';

  return (
    <div 
      onClick={() => onSelect(note)}
      className={`relative p-5 rounded-2xl cursor-pointer transition-all duration-200 glass-panel ${
        isSelected 
          ? 'ring-2 ring-indigo-500 bg-slate-800/90 shadow-xl shadow-indigo-500/10 border-indigo-500/40' 
          : 'glass-panel-hover shadow-lg shadow-black/20'
      }`}
    >
      {/* Top Meta Bar */}
      <div className="flex items-start justify-between gap-3 mb-3">
        {/* Category Badge with Source and Confidence */}
        <div className="flex items-center gap-1.5 flex-wrap">
          <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold tracking-wide ${
            categorySource === 'auto' 
              ? 'bg-blue-500/15 text-blue-400 border border-blue-500/30' 
              : 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/30'
          }`}>
            {categorySource === 'auto' ? (
              <Sparkles className="w-3 h-3 text-blue-400" />
            ) : (
              <CheckCircle2 className="w-3 h-3 text-emerald-400" />
            )}
            <span>{categoryValue}</span>
            <span className="text-[10px] opacity-75 font-mono">
              ({categorySource === 'auto' ? `${categoryConfidence}%` : 'manual'})
            </span>
          </span>

          {/* Relationship Count Indicator */}
          {relationshipsCount > 0 && (
            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-medium bg-purple-500/15 text-purple-300 border border-purple-500/30">
              <Link2 className="w-2.5 h-2.5" />
              {relationshipsCount} {relationshipsCount === 1 ? 'link' : 'links'}
            </span>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-1 opacity-80 hover:opacity-100" onClick={e => e.stopPropagation()}>
          <button
            onClick={() => onEdit(note)}
            className="p-1.5 rounded-lg text-slate-400 hover:text-indigo-400 hover:bg-slate-700/60 transition-colors"
            title="Edit Note"
          >
            <Edit3 className="w-3.5 h-3.5" />
          </button>
          <button
            onClick={() => onDelete(note._id || note.id)}
            className="p-1.5 rounded-lg text-slate-400 hover:text-red-400 hover:bg-slate-700/60 transition-colors"
            title="Delete Note"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Note Title */}
      <h3 className="text-base font-bold text-slate-100 group-hover:text-indigo-300 line-clamp-1 mb-2">
        {note.title}
      </h3>

      {/* Content Preview */}
      <p className="text-slate-300 text-xs line-clamp-3 leading-relaxed mb-4">
        {note.content}
      </p>

      {/* Semantic Tags with Source Indicators */}
      <div className="flex items-center gap-1.5 flex-wrap mb-4">
        {note.tags && note.tags.slice(0, 4).map((tag, idx) => {
          const tagName = typeof tag === 'string' ? tag : tag.name;
          const tagSource = typeof tag === 'string' ? 'auto' : (tag.source || 'auto');

          return (
            <span 
              key={idx}
              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium ${
                tagSource === 'manual' 
                  ? 'bg-emerald-950/60 text-emerald-300 border border-emerald-800/60' 
                  : 'bg-slate-800/80 text-slate-300 border border-slate-700/60'
              }`}
            >
              <TagIcon className="w-2.5 h-2.5 opacity-60" />
              <span>#{tagName}</span>
              <span className={`text-[9px] px-1 rounded ${
                tagSource === 'manual' ? 'bg-emerald-900/80 text-emerald-200' : 'bg-slate-700/80 text-slate-400'
              }`}>
                {tagSource}
              </span>
            </span>
          );
        })}
        {note.tags && note.tags.length > 4 && (
          <span className="text-[10px] text-slate-400 self-center">
            +{note.tags.length - 4} more
          </span>
        )}
      </div>

      {/* Footer Info & Reasoning Snippet */}
      <div className="pt-3 border-t border-slate-800/80 flex items-center justify-between text-[11px] text-slate-400">
        <div className="flex items-center gap-1">
          <Clock className="w-3 h-3 text-slate-400" />
          <span>{dateStr}</span>
        </div>

        <button 
          onClick={() => onSelect(note)}
          className="inline-flex items-center gap-1 text-indigo-400 hover:text-indigo-300 font-semibold group"
        >
          <Cpu className="w-3 h-3 text-indigo-400" />
          <span>Inspect Semantics</span>
          <ArrowUpRight className="w-3 h-3 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
        </button>
      </div>
    </div>
  );
}

