export class StorageService {
  /**
   * Initialize in-memory storage with bootstrapped relational links
   */
  static init() {
    if (inMemoryNotes.length === 0) {
      this.seedInitialData();
    }
  }

  static seedInitialData() {
    inMemoryNotes = INITIAL_SEED_NOTES.map((noteData, idx) => 
      createNoteObject(noteData, `seed_note_${idx + 1}`)
    );
    this.recomputeAllRelationships();
    console.log(`[Storage] Initialized with ${inMemoryNotes.length} contextual seed notes.`);
  }

  /**
   * Recalculate semantic relationships across all notes
   */
  static recomputeAllRelationships() {
    for (const note of inMemoryNotes) {
      const analysis = SemanticEngine.analyzeNote(note, inMemoryNotes, note._id);

      // Preserve manual relationships if any, otherwise update auto relationships
      const manualRels = (note.relationships || []).filter(r => r.source === 'manual');
      const autoRels = analysis.relationships.filter(r => 
        !manualRels.some(m => String(m.targetNoteId) === String(r.targetNoteId))
      );

      note.relationships = [...manualRels, ...autoRels];
    }
  }

  static getAllNotes({ category, tag, search } = {}) {
    let results = [...inMemoryNotes];

    if (category && category !== 'All') {
      results = results.filter(n => (n.category?.value || n.category) === category);
    }

    if (tag) {
      results = results.filter(n => 
        n.tags?.some(t => (typeof t === 'string' ? t : t.name).toLowerCase() === tag.toLowerCase())
      );
    }

    if (search) {
      const q = search.toLowerCase();
      results = results.filter(n => 
        n.title.toLowerCase().includes(q) || 
        n.content.toLowerCase().includes(q) ||
        n.tags?.some(t => (typeof t === 'string' ? t : t.name).toLowerCase().includes(q))
      );
    }

    return results.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }

  static getNoteById(id) {
    return inMemoryNotes.find(n => String(n._id) === String(id) || String(n.id) === String(id));
  }

  static createNote(data) {
    // 1. Run Semantic Analysis with current corpus
    const analysis = SemanticEngine.analyzeNote(data, inMemoryNotes);

    // Determine category based on manual override or auto inference
    const category = data.category?.source === 'manual' 
      ? {
          value: data.category.value || data.category,
          source: 'manual',
          confidence: 1.0,
          reasoning: 'Explicitly set by user during note creation'
        }
      : analysis.category;

    // Merge manual and auto tags
    const inputTags = Array.isArray(data.tags) ? data.tags : [];
    const mergedTags = [];
    const tagSeen = new Set();

    // Add user provided tags (marked as manual if user typed them)
    inputTags.forEach(t => {
      const name = (typeof t === 'string' ? t : t.name).toLowerCase().trim();
      if (name && !tagSeen.has(name)) {
        tagSeen.add(name);
        mergedTags.push(typeof t === 'string' ? {
          name,
          source: 'manual',
          confidence: 1.0,
          reasoning: 'User manually attached tag'
        } : t);
      }
    });

    // Add remaining auto-inferred tags
    analysis.tags.forEach(t => {
      if (!tagSeen.has(t.name)) {
        tagSeen.add(t.name);
        mergedTags.push(t);
      }
    });

    // Create note instance
    const newNote = createNoteObject({
      ...data,
      category,
      tags: mergedTags,
      relationships: analysis.relationships,
      keywords: analysis.keywords,
      semanticHistory: [
        {
          action: 'auto_classified',
          field: 'semantic_state',
          fromValue: null,
          toValue: { category: category.value, tagsCount: mergedTags.length, relsCount: analysis.relationships.length },
          timestamp: new Date(),
          notes: `Auto-inferred category '${category.value}' (${Math.round(category.confidence * 100)}% conf) and ${analysis.relationships.length} relationship links`
        }
      ]
    });

    inMemoryNotes.unshift(newNote);

    // Update relationship links across all existing notes
    this.recomputeAllRelationships();

    return newNote;
  }

  static updateNote(id, data) {
    const existingIndex = inMemoryNotes.findIndex(n => String(n._id) === String(id) || String(n.id) === String(id));
    if (existingIndex === -1) return null;

    const currentNote = inMemoryNotes[existingIndex];
    const now = new Date();
    const historyEvents = [...(currentNote.semanticHistory || [])];

    // Detect category change and record source/provenance
    let updatedCategory = currentNote.category;
    if (data.category) {
      const newCatVal = typeof data.category === 'object' ? data.category.value : data.category;
      const newCatSource = typeof data.category === 'object' ? (data.category.source || 'manual') : 'manual';

      if (newCatVal !== currentNote.category?.value || newCatSource !== currentNote.category?.source) {
        historyEvents.unshift({
          action: newCatSource === 'manual' ? 'category_manual_override' : 'category_updated',
          field: 'category',
          fromValue: currentNote.category,
          toValue: { value: newCatVal, source: newCatSource },
          timestamp: now,
          notes: `Category transitioned from [${currentNote.category?.source || 'auto'}] '${currentNote.category?.value}' to [${newCatSource}] '${newCatVal}'`
        });

        updatedCategory = {
          value: newCatVal,
          source: newCatSource,
          confidence: newCatSource === 'manual' ? 1.0 : (data.category.confidence || 0.8),
          reasoning: newCatSource === 'manual' 
            ? 'Manually edited and verified by user' 
            : (data.category.reasoning || currentNote.category?.reasoning || '')
        };
      }
    }

    // Process tag updates & detect manual additions / removals
    let updatedTags = currentNote.tags;
    if (data.tags) {
      updatedTags = data.tags.map(t => {
        if (typeof t === 'string') {
          return {
            name: t.trim().toLowerCase(),
            source: 'manual',
            confidence: 1.0,
            reasoning: 'User edited tag'
          };
        }
        return {
          name: t.name.trim().toLowerCase(),
          source: t.source || 'manual',
          confidence: t.confidence ?? (t.source === 'manual' ? 1.0 : 0.8),
          reasoning: t.reasoning || (t.source === 'manual' ? 'User accepted/edited tag' : 'Auto suggested')
        };
      });

      historyEvents.unshift({
        action: 'tags_updated',
        field: 'tags',
        fromValue: currentNote.tags.map(t => t.name),
        toValue: updatedTags.map(t => `${t.name} (${t.source})`),
        timestamp: now,
        notes: `Tags updated (${updatedTags.length} active tags)`
      });
    }

    // Process relationship modifications
    let updatedRelationships = currentNote.relationships;
    if (data.relationships) {
      updatedRelationships = data.relationships.map(r => ({
        targetNoteId: String(r.targetNoteId),
        targetTitle: r.targetTitle || '',
        relationType: r.relationType || 'related_to',
        source: r.source || 'manual',
        similarity: r.similarity || 0,
        reasoning: r.reasoning || (r.source === 'manual' ? 'Manually linked by user' : '')
      }));

      historyEvents.unshift({
        action: 'relationships_updated',
        field: 'relationships',
        fromValue: currentNote.relationships?.length || 0,
        toValue: updatedRelationships.length,
        timestamp: now,
        notes: `Relationships updated to ${updatedRelationships.length} connected notes`
      });
    }

    // Update note record
    const updatedNote = {
      ...currentNote,
      title: data.title !== undefined ? data.title.trim() : currentNote.title,
      content: data.content !== undefined ? data.content.trim() : currentNote.content,
      category: updatedCategory,
      tags: updatedTags,
      relationships: updatedRelationships,
      semanticHistory: historyEvents.slice(0, 30), // keep recent 30 events
      updatedAt: now
    };

    inMemoryNotes[existingIndex] = updatedNote;
    this.recomputeAllRelationships();

    return updatedNote;
  }

  static deleteNote(id) {
    const initialLength = inMemoryNotes.length;
    inMemoryNotes = inMemoryNotes.filter(n => String(n._id) !== String(id) && String(n.id) !== String(id));

    // Remove references to deleted note from other notes' relationships
    inMemoryNotes.forEach(note => {
      if (Array.isArray(note.relationships)) {
        note.relationships = note.relationships.filter(r => String(r.targetNoteId) !== String(id));
      }
    });

    return inMemoryNotes.length < initialLength;
  }

  static resetAndSeed() {
    this.seedInitialData();
    return inMemoryNotes;
  }

  static clearAll() {
    inMemoryNotes = [];
    return [];
  }
}

