/**
 * API client for Notes and Semantic Organization Engine
 */

const API_BASE = '/api';

export const api = {
  async getNotes(params = {}) {
    const query = new URLSearchParams();
    if (params.category && params.category !== 'All') query.append('category', params.category);
    if (params.tag) query.append('tag', params.tag);
    if (params.search) query.append('search', params.search);

    const res = await fetch(`${API_BASE}/notes?${query.toString()}`);
    if (!res.ok) throw new Error('Failed to fetch notes');
    return res.json();
  },

  async getNote(id) {
    const res = await fetch(`${API_BASE}/notes/${id}`);
    if (!res.ok) throw new Error('Failed to fetch note');
    return res.json();
  },

  async createNote(noteData) {
    const res = await fetch(`${API_BASE}/notes`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(noteData)
    });
    if (!res.ok) throw new Error('Failed to create note');
    return res.json();
  },

  async updateNote(id, noteData) {
    const res = await fetch(`${API_BASE}/notes/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(noteData)
    });
    if (!res.ok) throw new Error('Failed to update note');
    return res.json();
  },

  async deleteNote(id) {
    const res = await fetch(`${API_BASE}/notes/${id}`, {
      method: 'DELETE'
    });
    if (!res.ok) throw new Error('Failed to delete note');
    return res.json();
  },

  async analyzeSemantic(data) {
    const res = await fetch(`${API_BASE}/semantic/analyze`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!res.ok) throw new Error('Failed to run semantic analysis');
    return res.json();
  },

  async seedData() {
    const res = await fetch(`${API_BASE}/semantic/seed`, {
      method: 'POST'
    });
    if (!res.ok) throw new Error('Failed to seed data');
    return res.json();
  },

  async clearData() {
    const res = await fetch(`${API_BASE}/semantic/clear`, {
      method: 'POST'
    });
    if (!res.ok) throw new Error('Failed to clear data');
    return res.json();
  }
};

