  const relationshipsCount = note.relationships?.length || 0;

  // Format date
  const dateStr = note.createdAt 
    ? new Date(note.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    : 'Recently';

  return (
    <div 
      onClick={() => onSelect(note)}
      className={`relative p-5 rounded-2xl cursor-pointer transition-all duration-200 glass-panel ${
        isSelected 
          ? 'ring-2 ring-indigo-500 bg-slate-800/90 shadow-xl shadow-indigo-500/10 border-indigo-500/40' 
          : 'glass-panel-hover shadow-lg shadow-black/20'
      }`}
    >
