export function SeedDataLoader({ onDataLoaded }) {
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleSeed = async () => {
    try {
      setLoading(true);
      const res = await api.seedData();
      setMessage('Sample notes loaded with semantic links!');
      if (onDataLoaded) onDataLoaded();
      setTimeout(() => setMessage(''), 3000);
    } catch (err) {
      console.error(err);
      setMessage('Failed to load sample dataset');
    } finally {
      setLoading(false);
    }
  };

  const handleClear = async () => {
    if (!window.confirm('Clear all notes in the workspace?')) return;
    try {
      setLoading(true);
      await api.clearData();
      setMessage('Workspace cleared');
      if (onDataLoaded) onDataLoaded();
      setTimeout(() => setMessage(''), 3000);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex items-center gap-2">
      {message && (
        <span className="text-xs text-indigo-300 bg-indigo-950/70 border border-indigo-800/60 px-2.5 py-1 rounded-lg animate-fade-in flex items-center gap-1">
          <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
          {message}
        </span>
      )}

      <button
        onClick={handleSeed}
        disabled={loading}
        className="px-3 py-1.5 rounded-xl bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-300 border border-indigo-500/30 text-xs font-semibold flex items-center gap-1.5 transition-all shadow-sm"
        title="Load rich pre-indexed sample notes across Web Dev, DevOps & DB"
      >
        <Sparkles className="w-3.5 h-3.5 text-indigo-400" />
        <span>Load Demo Data</span>
      </button>

      <button
        onClick={handleClear}
        disabled={loading}
        className="p-1.5 rounded-xl text-slate-400 hover:text-red-400 hover:bg-slate-800/60 border border-transparent hover:border-slate-700 transition-all text-xs"
        title="Clear all notes"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Filter, Sparkles, CheckCircle2, FileText, Plus } from 'lucide-react';
import { NoteCard } from './NoteCard';

export function NoteList({ 
  notes, 
  onSelectNote, 
  onEditNote, 
  onDeleteNote, 
  onCreateClick, 
  selectedNoteId 
}) {
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [provenanceFilter, setProvenanceFilter] = useState('all'); // 'all' | 'auto' | 'manual'

  // Extract available unique categories with counts
  const categoryCounts = { All: notes.length };
  notes.forEach(n => {
    const cat = n.category?.value || 'General';
    categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
  });

  // Filter notes
  const filteredNotes = notes.filter(note => {
    // 1. Search Query
    const q = search.toLowerCase();
    const matchesSearch = !search || 
      note.title.toLowerCase().includes(q) || 
      note.content.toLowerCase().includes(q) ||
      note.tags?.some(t => (typeof t === 'string' ? t : t.name).toLowerCase().includes(q));

    // 2. Category Filter
    const cat = note.category?.value || 'General';
    const matchesCategory = selectedCategory === 'All' || cat === selectedCategory;

    // 3. Provenance Filter (Auto vs Manual)
    const source = note.category?.source || 'auto';
    const matchesProvenance = 
      provenanceFilter === 'all' || 
      (provenanceFilter === 'auto' && source === 'auto') ||
      (provenanceFilter === 'manual' && source === 'manual');

    return matchesSearch && matchesCategory && matchesProvenance;
  });

  return (
    <div className="space-y-5">
      {/* Search & Filter Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        {/* Search Bar */}
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search notes, terms, or semantic tags..."
            className="w-full pl-10 pr-4 py-2 rounded-xl bg-slate-900 border border-slate-800 text-slate-100 placeholder-slate-500 text-xs focus:ring-2 focus:ring-indigo-500 focus:outline-none"
          />
          {search && (
            <button 
              onClick={() => setSearch('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-200 text-xs"
            >
              Clear
            </button>
          )}
        </div>

        {/* Provenance Filter Pills */}
        <div className="flex items-center gap-1 p-1 bg-slate-900 border border-slate-800 rounded-xl text-xs">
          <button
            onClick={() => setProvenanceFilter('all')}
            className={`px-2.5 py-1 rounded-lg font-medium transition-colors ${
              provenanceFilter === 'all' 
                ? 'bg-slate-800 text-slate-100 shadow-sm' 
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            All Notes ({notes.length})
          </button>
          <button
            onClick={() => setProvenanceFilter('auto')}
            className={`px-2.5 py-1 rounded-lg font-medium flex items-center gap-1 transition-colors ${
              provenanceFilter === 'auto' 
                ? 'bg-blue-600/30 text-blue-300 border border-blue-500/40 shadow-sm' 
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            <Sparkles className="w-3 h-3 text-blue-400" />
            Auto ({notes.filter(n => (n.category?.source || 'auto') === 'auto').length})
          </button>
          <button
            onClick={() => setProvenanceFilter('manual')}
            className={`px-2.5 py-1 rounded-lg font-medium flex items-center gap-1 transition-colors ${
              provenanceFilter === 'manual' 
                ? 'bg-emerald-600/30 text-emerald-300 border border-emerald-500/40 shadow-sm' 
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            <CheckCircle2 className="w-3 h-3 text-emerald-400" />
            Manual ({notes.filter(n => (n.category?.source || 'auto') === 'manual').length})
          </button>
        </div>
      </div>

      {/* Category Pills Bar */}
      <div className="flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-none text-xs">
        {Object.entries(categoryCounts).map(([catName, count]) => (
          <button
            key={catName}
            onClick={() => setSelectedCategory(catName)}
            className={`px-3 py-1 rounded-lg font-medium whitespace-nowrap transition-all ${
              selectedCategory === catName
                ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                : 'bg-slate-900/80 hover:bg-slate-800 text-slate-300 border border-slate-800'
            }`}
          >
            <span>{catName}</span>
            <span className="ml-1.5 text-[10px] opacity-75 font-mono">({count})</span>
          </button>
        ))}
      </div>

      {/* Notes Grid */}
      {filteredNotes.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredNotes.map(note => (
            <NoteCard
              key={note._id || note.id}
              note={note}
              isSelected={selectedNoteId && String(selectedNoteId) === String(note._id || note.id)}
              onSelect={onSelectNote}
              onEdit={onEditNote}
              onDelete={onDeleteNote}
            />
          ))}
        </div>
      ) : (
        <div className="p-12 text-center rounded-2xl bg-slate-900/50 border border-slate-800 space-y-4">
          <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 border border-indigo-500/30 text-indigo-400 flex items-center justify-center mx-auto">
            <FileText className="w-6 h-6" />
          </div>
          <div>
            <h4 className="text-base font-bold text-slate-200">No notes found</h4>
            <p className="text-xs text-slate-400 max-w-sm mx-auto mt-1">
              Create a new note to watch the Semantic Engine infer categories, related terms, and conceptual links in real-time.
            </p>
          </div>
          <button
            onClick={onCreateClick}
            className="px-4 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-lg shadow-indigo-600/30 inline-flex items-center gap-1.5"
          >
            <Plus className="w-4 h-4" /> Create First Note
          </button>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, 
  Plus, 
  Network, 
  ListFilter, 
  Sparkles, 
  CheckCircle2, 
  Layers, 
  Link2, 
  Activity,
  Code2,
  BookOpen
} from 'lucide-react';
import { api } from './services/api';
import { NoteList } from './components/NoteList';
import { NoteForm } from './components/NoteForm';
import { SemanticInspector } from './components/SemanticInspector';
import { SemanticGraph } from './components/SemanticGraph';
import { SeedDataLoader } from './components/SeedDataLoader';

export function App() {
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState('list'); // 'list' | 'graph'

  // Inspector & Form states
  const [selectedNote, setSelectedNote] = useState(null);
  const [isCreating, setIsCreating] = useState(false);
  const [editingNote, setEditingNote] = useState(null);

  // Load Notes
  const loadNotes = async () => {
    try {
      setLoading(true);
      const res = await api.getNotes();
      if (res.success) {
        setNotes(res.data);

        // Update selected note if open
        if (selectedNote) {
          const fresh = res.data.find(n => String(n._id || n.id) === String(selectedNote._id || selectedNote.id));
          if (fresh) setSelectedNote(fresh);
        }
      }
    } catch (err) {
      console.error('Failed to load notes:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadNotes();
  }, []);

  // Create Note
  const handleCreateNote = async (noteData) => {
    try {
      const res = await api.createNote(noteData);
      if (res.success) {
        setIsCreating(false);
        await loadNotes();
        // Automatically open the newly created note in inspector so judges see instant inference
        setSelectedNote(res.data);
      }
    } catch (err) {
      console.error('Failed to create note:', err);
      alert('Error creating note: ' + err.message);
    }
  };

  // Update Note
  const handleUpdateNote = async (id, updatedData) => {
    try {
      const res = await api.updateNote(id, updatedData);
      if (res.success) {
        setEditingNote(null);
        await loadNotes();
        if (selectedNote && String(selectedNote._id || selectedNote.id) === String(id)) {
          setSelectedNote(res.data);
        }
      }
    } catch (err) {
      console.error('Failed to update note:', err);
      alert('Error updating note: ' + err.message);
    }
  };

  // Delete Note
  const handleDeleteNote = async (id) => {
    if (!window.confirm('Delete this note and prune related links?')) return;
    try {
      const res = await api.deleteNote(id);
      if (res.success) {
        if (selectedNote && String(selectedNote._id || selectedNote.id) === String(id)) {
          setSelectedNote(null);
        }
        await loadNotes();
      }
    } catch (err) {
      console.error('Failed to delete note:', err);
    }
  };

  // Metrics computation
  const totalNotes = notes.length;
  const autoCategoriesCount = notes.filter(n => (n.category?.source || 'auto') === 'auto').length;
  const manualCategoriesCount = notes.filter(n => (n.category?.source || 'auto') === 'manual').length;

  const totalRelationships = notes.reduce((acc, n) => acc + (n.relationships?.length || 0), 0);
  const uniqueCategories = new Set(notes.map(n => n.category?.value || 'General')).size;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col">
      {/* Top Navigation Bar */}
      <header className="border-b border-slate-800 bg-slate-900/80 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          {/* Logo & Brand */}
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20 text-white">
              <BrainCircuit className="w-6 h-6" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="font-extrabold text-base tracking-tight text-white">
                  SemanticNotes
                </h1>
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-500/20 text-indigo-300 border border-indigo-500/40 uppercase tracking-wide">
                  Semantic Engine MVP
                </span>
              </div>
              <p className="text-[11px] text-slate-400">
                Explainable auto-classification, relationship discovery & provenance tracking
              </p>
            </div>
          </div>

          {/* Right actions */}
          <div className="flex items-center gap-3">
            <SeedDataLoader onDataLoaded={loadNotes} />

            <button
              onClick={() => { setIsCreating(true); setEditingNote(null); }}
              className="px-4 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-lg shadow-indigo-600/30 flex items-center gap-1.5 transition-all"
            >
              <Plus className="w-4 h-4" />
              <span>New Note</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 flex-1 w-full space-y-6">
        {/* KPI / Live Semantic Metric Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3.5">
          <div className="p-4 rounded-2xl bg-slate-900/70 border border-slate-800/80 shadow-md flex items-center gap-3.5">
            <div className="p-2.5 rounded-xl bg-indigo-500/10 text-indigo-400 border border-indigo-500/20">
              <BookOpen className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-extrabold text-slate-100">{totalNotes}</div>
              <div className="text-[11px] text-slate-400 font-medium">Total Notes in Corpus</div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-slate-900/70 border border-slate-800/80 shadow-md flex items-center gap-3.5">
            <div className="p-2.5 rounded-xl bg-blue-500/10 text-blue-400 border border-blue-500/20">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-extrabold text-blue-400">{autoCategoriesCount}</div>
              <div className="text-[11px] text-slate-400 font-medium">Auto-Inferred Categories</div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-slate-900/70 border border-slate-800/80 shadow-md flex items-center gap-3.5">
            <div className="p-2.5 rounded-xl bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
              <CheckCircle2 className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-extrabold text-emerald-400">{manualCategoriesCount}</div>
              <div className="text-[11px] text-slate-400 font-medium">User-Verified Overrides</div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-slate-900/70 border border-slate-800/80 shadow-md flex items-center gap-3.5">
            <div className="p-2.5 rounded-xl bg-purple-500/10 text-purple-400 border border-purple-500/20">
              <Link2 className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-extrabold text-purple-400">{totalRelationships}</div>
              <div className="text-[11px] text-slate-400 font-medium">Semantic Graph Links</div>
            </div>
          </div>
        </div>

        {/* Create / Edit Note Modal */}
        {(isCreating || editingNote) && (
          <div className="animate-fade-in">
            <NoteForm
              initialNote={editingNote}
              onSave={(data) => {
                if (editingNote) {
                  handleUpdateNote(editingNote._id || editingNote.id, data);
                } else {
                  handleCreateNote(data);
                }
              }}
              onCancel={() => {
                setIsCreating(false);
                setEditingNote(null);
              }}
            />
          </div>
        )}

        {/* View Switcher (Notes List vs Semantic Graph) */}
        <div className="flex items-center justify-between border-b border-slate-800 pb-3">
          <div className="flex items-center gap-2">
            <button
              onClick={() => setActiveView('list')}
              className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1.5 transition-all ${
                activeView === 'list'
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                  : 'bg-slate-900 text-slate-400 hover:text-slate-200 border border-slate-800'
              }`}
            >
              <ListFilter className="w-3.5 h-3.5" />
              Notes Feed
            </button>

            <button
              onClick={() => setActiveView('graph')}
              className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1.5 transition-all ${
                activeView === 'graph'
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                  : 'bg-slate-900 text-slate-400 hover:text-slate-200 border border-slate-800'
              }`}
            >
              <Network className="w-3.5 h-3.5" />
              Semantic Graph
            </button>
          </div>

          <div className="text-xs text-slate-400 hidden sm:block">
            Click any note to open the <span className="text-indigo-400 font-semibold">Semantic Inspector</span>
          </div>
        </div>

        {/* Active View Container */}
        {activeView === 'list' ? (
          <NoteList
            notes={notes}
            selectedNoteId={selectedNote?._id || selectedNote?.id}
            onSelectNote={(n) => setSelectedNote(n)}
            onEditNote={(n) => { setEditingNote(n); setIsCreating(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
            onDeleteNote={handleDeleteNote}
            onCreateClick={() => { setIsCreating(true); setEditingNote(null); }}
          />
        ) : (
          <SemanticGraph
            notes={notes}
            selectedNoteId={selectedNote?._id || selectedNote?.id}
            onSelectNote={(n) => setSelectedNote(n)}
          />
        )}
      </main>

      {/* Semantic Inspector Side Drawer */}
      {selectedNote && (
        <SemanticInspector
          note={selectedNote}
          allNotes={notes}
          onClose={() => setSelectedNote(null)}
          onUpdateNote={handleUpdateNote}
        />
      )}

      {/* Footer */}
      <footer className="border-t border-slate-800/80 py-4 bg-slate-950 text-center text-xs text-slate-500">
        Semantic Organization Engine • Deterministic TF-IDF & Cosine Similarity • State Tracking & Provenance
      </footer>
    </div>
  );
}
export default App;

