  StorageService.resetAndSeed();
  const allNotes = StorageService.getAllNotes();

  const candidateNote = {
    title: 'React State Management with Hooks & Context',
    content: 'Using useState, useReducer, and useContext in React functional components for scalable UI state and component lifecycle.'
  };

  const analysis = SemanticEngine.analyzeNote(candidateNote, allNotes);
  console.log('Inferred Category:', analysis.category);
  console.log('Inferred Tags:', analysis.tags.map(t => `${t.name} [${t.source}] (${t.confidence})`));
  console.log('Discovered Relationships:', analysis.relationships.map(r => `${r.relationType} -> "${r.targetTitle}" (${r.similarity * 100}%)`));

  console.assert(analysis.category.value === 'Frontend Architecture', 'Category should infer Frontend Architecture');
  console.assert(analysis.category.source === 'auto', 'Default category source should be auto');
  console.assert(analysis.relationships.length > 0, 'Should discover relationship to existing React note');
  console.log('✅ Auto-classification & context-aware inference test passed.\n');

  // Test 3: Note Creation & Relationship Graph Recomputation
  console.log('--- Test 3: End-to-End Note Creation in Storage ---');
  const createdNote = StorageService.createNote(candidateNote);
  console.log('Created Note ID:', createdNote._id);
  console.log('Created Note Category Source:', createdNote.category.source);
  console.log('Created Note Tags Count:', createdNote.tags.length);
  console.log('Created Note Relationships Count:', createdNote.relationships.length);
  console.log('Audit History Log:', createdNote.semanticHistory);

  console.assert(createdNote.semanticHistory.length > 0, 'Audit history log must record auto-classification event');
  console.log('✅ Note creation & audit logging test passed.\n');

  // Test 4: User Manual Override & State Transition
  console.log('--- Test 4: User Manual Override & History Transition ---');
  const updatedNote = StorageService.updateNote(createdNote._id, {
    category: { value: 'Frontend Performance & UI', source: 'manual' },
    tags: [
      { name: 'react', source: 'manual', confidence: 1.0 },
      { name: 'hooks', source: 'manual', confidence: 1.0 },
      { name: 'custom-tag', source: 'manual', confidence: 1.0 }
    ]
  });

  console.log('Updated Category Source:', updatedNote.category.source);
  console.log('Updated Category Value:', updatedNote.category.value);
  console.log('Updated History Log:', updatedNote.semanticHistory.map(h => `${h.action}: ${h.notes}`));

  console.assert(updatedNote.category.source === 'manual', 'Category source should be transitioned to manual');
  console.assert(updatedNote.semanticHistory.some(h => h.action === 'category_manual_override'), 'Audit trail must record category_manual_override');
  console.log('✅ User manual override & provenance transition test passed.\n');

  // Test 5: Multi-type Relationships (synonym_of / extends / part_of)
  console.log('--- Test 5: Multi-type Relationship Semantics ---');
  const duplicateCandidate = {
    title: 'Express REST API Routing & Middleware',
    content: 'Building scalable Node.js HTTP servers using Express router middleware for authentication and request validation.'
  };
  const dupAnalysis = SemanticEngine.analyzeNote(duplicateCandidate, allNotes);
  const dupRelation = dupAnalysis.relationships.find(r => r.targetTitle.includes('Express REST API'));
  console.log('Duplicate test relation type:', dupRelation?.relationType, 'Reason:', dupRelation?.reasoning);
  console.assert(dupRelation?.relationType === 'synonym_of' || dupRelation?.relationType === 'related_to', 'Should detect high concept similarity');
  console.log('✅ Multi-type relationship semantics test passed.\n');

  console.log('🎉 ALL 5 SEMANTIC ORGANIZATION VERIFICATION TESTS PASSED PERFECTLY!');
}

runTests();

