import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:5000',
        changeOrigin: true
      }
    }
  }
});

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        brand: {
          50: '#eef2ff',
          100: '#e0e7ff',
          200: '#c7d2fe',
          300: '#a5b4fc',
          400: '#818cf8',
          500: '#6366f1',
          600: '#4f46e5',
          700: '#4338ca',
          800: '#3730a3',
          900: '#312e81',
        },
        semantic: {
          auto: '#3b82f6',
          manual: '#10b981',
          related: '#8b5cf6',
          partof: '#f59e0b',
          synonym: '#ec4899',
          extends: '#06b6d4'
        }
      }
    },
  },
  plugins: [],
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

/**
 * Note Model with Rich Semantic Organization Metadata
 * 
 * Supports both MongoDB Mongoose Schema and In-Memory object representations.
 */

export const NoteSchemaDefinition = {
  title: {
    type: String,
    required: true,
    trim: true,
  },
  content: {
    type: String,
    required: true,
  },
  // Unified category with provenance and reasoning
  category: {
    value: { type: String, default: 'General' },
    source: { type: String, enum: ['auto', 'manual'], default: 'auto' },
    confidence: { type: Number, default: 0.5 },
    reasoning: { type: String, default: 'Default baseline classification' }
  },
  // Rich tags with provenance, confidence, and source tracking
  tags: [
    {
      name: { type: String, required: true },
      source: { type: String, enum: ['auto', 'manual'], default: 'auto' },
      confidence: { type: Number, default: 0.7 },
      reasoning: { type: String, default: 'Extracted from content keywords' }
    }
  ],
  // Discovered or user-defined relationships with target notes
  relationships: [
    {
      targetNoteId: { type: String, required: true },
      targetTitle: { type: String, default: '' },
      relationType: {
        type: String,
        enum: ['related_to', 'part_of', 'synonym_of', 'extends'],
        default: 'related_to'
      },
      source: { type: String, enum: ['auto', 'manual'], default: 'auto' },
      similarity: { type: Number, default: 0 },
      reasoning: { type: String, default: '' }
    }
  ],
  // Key semantic descriptors extracted via TF-IDF
  keywords: [
    {
      term: { type: String },
      weight: { type: Number }
    }
  ],
  // Audit trail of auto -> manual transitions and edits
  semanticHistory: [
    {
      action: { type: String, required: true }, // 'auto_classified', 'category_override', 'tag_accepted', 'tag_removed', 'relation_modified'
      field: { type: String },
      fromValue: {},
      toValue: {},
      timestamp: { type: Date, default: Date.now },
      notes: { type: String }
    }
  ],
  createdAt: {
    type: Date,
    default: Date.now
  },
  updatedAt: {
    type: Date,
    default: Date.now
  }
};

/**
 * Creates a normalized note object with valid defaults
 */
export function createNoteObject(data, id = null) {
  const now = new Date();

  // Format tags properly whether passed as strings or objects
  const formattedTags = Array.isArray(data.tags)
    ? data.tags.map(tag => {
        if (typeof tag === 'string') {
          return {
            name: tag.trim().toLowerCase(),
            source: data.source || 'auto',
            confidence: 0.8,
            reasoning: 'Extracted term'
          };
        }
        return {
          name: tag.name?.trim().toLowerCase() || 'tag',
          source: tag.source || 'auto',
          confidence: tag.confidence ?? 0.8,
          reasoning: tag.reasoning || ''
        };
      })
    : [];

  // Format category
  let formattedCategory = {
    value: 'General',
    source: 'auto',
    confidence: 0.5,
    reasoning: 'Default baseline'
  };

  if (typeof data.category === 'string') {
    formattedCategory = {
      value: data.category.trim(),
      source: data.categorySource || 'auto',
      confidence: data.categoryConfidence || 0.75,
      reasoning: data.categoryReasoning || 'Assigned category'
    };
  } else if (data.category && typeof data.category === 'object') {
    formattedCategory = {
      value: data.category.value || 'General',
      source: data.category.source || 'auto',
      confidence: data.category.confidence ?? 0.75,
      reasoning: data.category.reasoning || ''
    };
  }

  // Format relationships
  const formattedRelationships = Array.isArray(data.relationships)
    ? data.relationships.map(rel => ({
        targetNoteId: String(rel.targetNoteId),
        targetTitle: rel.targetTitle || '',
        relationType: rel.relationType || 'related_to',
        source: rel.source || 'auto',
        similarity: Number(rel.similarity || 0),
        reasoning: rel.reasoning || ''
      }))
    : [];

  return {
    _id: id || data._id || data.id || ('note_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8)),
    title: (data.title || 'Untitled Note').trim(),
    content: (data.content || '').trim(),
    category: formattedCategory,
    tags: formattedTags,
    relationships: formattedRelationships,
    keywords: data.keywords || [],
    semanticHistory: Array.isArray(data.semanticHistory) ? data.semanticHistory : [
      {
        action: 'created',
        field: 'note',
        fromValue: null,
        toValue: 'initial_state',
        timestamp: now,
        notes: `Note created with ${formattedCategory.source} category '${formattedCategory.value}'`
      }
    ],
    createdAt: data.createdAt ? new Date(data.createdAt) : now,
    updatedAt: now
  };
}

/**
 * Semantic Organization Engine
 * 
 * Deterministic, inspectable, and context-aware natural language & relation engine.
 * Computes TF-IDF vectors, category inference, tag propagation, relationship discovery,
 * and human-readable explainability reasoning.
 */

// Domain stop-words to eliminate uninformative noise
const STOP_WORDS = new Set([
  'a', 'about', 'above', 'after', 'again', 'against', 'all', 'am', 'an', 'and', 'any', 'are', 'aren\'t', 'as', 'at',
  'be', 'because', 'been', 'before', 'being', 'below', 'between', 'both', 'but', 'by', 'can', 'can\'t', 'cannot',
  'could', 'couldn\'t', 'did', 'didn\'t', 'do', 'does', 'doesn\'t', 'doing', 'don\'t', 'down', 'during', 'each',
  'few', 'for', 'from', 'further', 'had', 'hadn\'t', 'has', 'hasn\'t', 'have', 'haven\'t', 'having', 'he', 'he\'d',
  'he\'ll', 'he\'s', 'her', 'here', 'here\'s', 'hers', 'herself', 'him', 'himself', 'his', 'how', 'how\'s', 'i',
  'i\'d', 'i\'ll', 'i\'m', 'i\'ve', 'if', 'in', 'into', 'is', 'isn\'t', 'it', 'it\'s', 'its', 'itself', 'let\'s',
  'me', 'more', 'most', 'mustn\'t', 'my', 'myself', 'no', 'nor', 'not', 'of', 'off', 'on', 'once', 'only', 'or',
  'other', 'ought', 'our', 'ours', 'ourselves', 'out', 'over', 'own', 'same', 'shan\'t', 'she', 'she\'d', 'she\'ll',
  'she\'s', 'should', 'shouldn\'t', 'so', 'some', 'such', 'than', 'that', 'that\'s', 'the', 'their', 'theirs',
  'them', 'themselves', 'then', 'there', 'there\'s', 'these', 'they', 'they\'d', 'they\'ll', 'they\'re', 'they\'ve',
  'this', 'those', 'through', 'to', 'too', 'under', 'until', 'up', 'very', 'was', 'wasn\'t', 'we', 'we\'d', 'we\'ll',
  'we\'re', 'we\'ve', 'were', 'weren\'t', 'what', 'what\'s', 'when', 'when\'s', 'where', 'where\'s', 'which',
  'while', 'who', 'who\'s', 'whom', 'why', 'why\'s', 'with', 'won\'t', 'would', 'wouldn\'t', 'you', 'you\'d',
  'you\'ll', 'you\'re', 'you\'ve', 'your', 'yours', 'yourself', 'yourselves', 'also', 'note', 'notes', 'make',
  'making', 'use', 'using', 'need', 'needs', 'will', 'want', 'like', 'good', 'well', 'just', 'get', 'etc'
]);

// Contextual fallback archetypes for cold-start bootstrapping
const DOMAIN_ONTOLOGY = {
  'Frontend Architecture': ['react', 'vue', 'angular', 'component', 'props', 'state', 'hook', 'ui', 'css', 'tailwind', 'html', 'dom', 'jsx', 'tsx', 'vite', 'render', 'frontend', 'responsive'],
  'Backend & APIs': ['express', 'node', 'nodejs', 'api', 'rest', 'graphql', 'endpoint', 'server', 'middleware', 'router', 'crud', 'backend', 'microservice', 'http', 'jwt', 'auth'],
  'Database & Storage': ['mongodb', 'postgres', 'postgresql', 'sql', 'nosql', 'schema', 'mongoose', 'query', 'index', 'database', 'table', 'collection', 'redis', 'cache', 'orm'],
  'Cloud & DevOps': ['docker', 'kubernetes', 'k8s', 'aws', 'gcp', 'azure', 'ci/cd', 'pipeline', 'deployment', 'container', 'serverless', 'terraform', 'nginx', 'devops', 'cloud'],
  'Machine Learning & AI': ['ai', 'ml', 'model', 'dataset', 'embedding', 'vector', 'neural', 'llm', 'training', 'prompt', 'gemini', 'gpt', 'classifier', 'inference', 'semantic', 'nlp'],
  'Product & Workflow': ['meeting', 'sprint', 'roadmap', 'agile', 'kanban', 'feature', 'bug', 'jira', 'task', 'backlog', 'deadline', 'okr', 'user', 'story', 'hackathon'],
  'Security & Auth': ['security', 'oauth', 'jwt', 'token', 'encryption', 'password', 'cors', 'xss', 'csrf', 'vulnerability', 'permission', 'role', 'session']
};

/**
 * Tokenize and normalize text into clean semantic words & tech keywords
 */
export function tokenize(text) {
  if (!text) return [];

  // Normalize casing and clean punctuation while preserving tech keywords (e.g. node.js, ci/cd)
  const normalized = text.toLowerCase()
    .replace(/([a-z])\.([a-z])/g, '$1_$2') // preserve node.js as node_js
    .replace(/[\/\-]/g, ' ');

  const rawTokens = normalized.match(/[a-z0-9_]{2,}/g) || [];

  return rawTokens
    .map(t => t.replace(/_/g, '.'))
    .filter(token => !STOP_WORDS.has(token) && token.length > 1);
}

/**
 * Extract word frequency dictionary
 */
export function getTermFrequencies(tokens) {
  const tf = {};
  tokens.forEach(token => {
    tf[token] = (tf[token] || 0) + 1;
  });
  return tf;
}

/**
 * Compute TF-IDF keyword weights given document tokens and full corpus
 */
export function computeTfIdf(tokens, corpusTokensList) {
  const tf = getTermFrequencies(tokens);
  const totalDocs = Math.max(corpusTokensList.length, 1);
  const docLength = Math.max(tokens.length, 1);

  const tfIdfScores = [];

  for (const [term, count] of Object.entries(tf)) {
    // Term frequency normalized by doc length
    const termTf = count / docLength;

    // Document frequency (how many existing docs contain this term)
    let docFreq = 0;
    for (const docTokens of corpusTokensList) {
      if (docTokens.includes(term)) docFreq++;
    }

    // Smooth inverse document frequency
    const idf = Math.log(1 + (totalDocs / (1 + docFreq)));
    const score = termTf * idf;

    tfIdfScores.push({ term, weight: Number(score.toFixed(4)), rawCount: count });
  }

  // Sort descending by importance
  return tfIdfScores.sort((a, b) => b.weight - a.weight);
}

/**
 * Cosine Similarity between two term-frequency maps
 */
export function computeCosineSimilarity(tf1, tf2) {
  const allTerms = new Set([...Object.keys(tf1), ...Object.keys(tf2)]);
  if (allTerms.size === 0) return 0;

  let dotProduct = 0;
  let mag1 = 0;
  let mag2 = 0;

  for (const term of allTerms) {
    const val1 = tf1[term] || 0;
    const val2 = tf2[term] || 0;

    dotProduct += val1 * val2;
    mag1 += val1 * val1;
    mag2 += val2 * val2;
  }

  if (mag1 === 0 || mag2 === 0) return 0;
  return dotProduct / (Math.sqrt(mag1) * Math.sqrt(mag2));
}

/**
 * Jaccard token overlap similarity
 */
export function computeJaccardSimilarity(tokens1, tokens2) {
  const set1 = new Set(tokens1);
  const set2 = new Set(tokens2);

  const intersection = new Set([...set1].filter(x => set2.has(x)));
  const union = new Set([...set1, ...set2]);

  if (union.size === 0) return 0;
  return intersection.size / union.size;
}

/**
 * Main Semantic Analysis Engine
 * Evaluates candidate note against existing notes in database
 */
export class SemanticEngine {
  /**
   * Run full semantic inference on a note
   * @param {Object} input - { title, content, existingCategory, existingTags, manualOverrides }
   * @param {Array} allNotes - Existing notes in the database (context)
   */
  static analyzeNote(input, allNotes = [], targetNoteId = null) {
    const { title = '', content = '', category = null, tags = [] } = input;

    // Filter out target note itself from comparison corpus
    const otherNotes = allNotes.filter(n => String(n._id || n.id) !== String(targetNoteId));

    const combinedText = `${title} ${title} ${content}`; // title weighted 2x
    const tokens = tokenize(combinedText);
    const titleTokens = tokenize(title);
    const contentTokens = tokenize(content);

    const currentTf = getTermFrequencies(tokens);

    // Build token corpus for TF-IDF calculations
    const corpusTokensList = otherNotes.map(n => tokenize(`${n.title} ${n.content}`));
    const keywords = computeTfIdf(tokens, corpusTokensList).slice(0, 10);

    // 1. INFER CATEGORY
    const categoryInference = this.inferCategory({
      tokens,
      titleTokens,
      keywords,
      existingCategory: category,
      otherNotes
    });

    // 2. INFER TAGS
    const tagInference = this.inferTags({
      tokens,
      keywords,
      existingTags: tags,
      otherNotes,
      inferredCategory: categoryInference.value
    });

    // 3. INFER RELATIONSHIPS
    const relationshipInference = this.inferRelationships({
      currentNote: { title, content, tokens, tf: currentTf, tags: tagInference.tags },
      otherNotes
    });

    return {
      category: categoryInference,
      tags: tagInference.tags,
      relationships: relationshipInference,
      keywords,
      debug: {
        totalTokens: tokens.length,
        comparedAgainstCount: otherNotes.length,
        topTerms: keywords.map(k => `${k.term} (${k.weight})`).slice(0, 5)
      }
    };
  }

  /**
   * Infer category with explainable logic and confidence scoring
   */
  static inferCategory({ tokens, titleTokens, keywords, existingCategory, otherNotes }) {
    // If user has explicitly manually set category, preserve with 'manual' source
    if (existingCategory && existingCategory.source === 'manual') {
      return {
        value: existingCategory.value,
        source: 'manual',
        confidence: 1.0,
        reasoning: 'User manually specified and locked category'
      };
    }

    const categoryScores = new Map();
    const categoryReasoning = new Map();

    // Strategy A: Contextual learning from existing notes in database
    for (const note of otherNotes) {
      const noteCategory = note.category?.value || note.category;
      if (!noteCategory || noteCategory === 'General') continue;

      const noteTokens = tokenize(`${note.title} ${note.content}`);
      const jaccard = computeJaccardSimilarity(tokens, noteTokens);

      const sharedTerms = tokens.filter(t => noteTokens.includes(t));

      if (sharedTerms.length > 0) {
        const weight = (note.category?.source === 'manual' ? 1.4 : 1.0) * (jaccard * 2 + (sharedTerms.length * 0.15));
        const currentScore = categoryScores.get(noteCategory) || 0;
        categoryScores.set(noteCategory, currentScore + weight);

        if (!categoryReasoning.has(noteCategory) || categoryReasoning.get(noteCategory).sharedCount < sharedTerms.length) {
          categoryReasoning.set(noteCategory, {
            sampleNoteTitle: note.title,
            sharedTerms: Array.from(new Set(sharedTerms)).slice(0, 4),
            sharedCount: sharedTerms.length
          });
        }
      }
    }

    // Strategy B: Domain ontology matching for cold-start bootstrapping
    for (const [catName, catKeywords] of Object.entries(DOMAIN_ONTOLOGY)) {
      const matchedKeywords = tokens.filter(t => catKeywords.includes(t));
      if (matchedKeywords.length > 0) {
        // Boost if matches are in title
        const titleMatches = titleTokens.filter(t => catKeywords.includes(t));
        const ontologyScore = (matchedKeywords.length * 0.4) + (titleMatches.length * 0.8);

        const currentScore = categoryScores.get(catName) || 0;
        categoryScores.set(catName, currentScore + ontologyScore);

        if (!categoryReasoning.has(catName)) {
          categoryReasoning.set(catName, {
            sampleNoteTitle: 'Domain Ontology Knowledge Base',
            sharedTerms: Array.from(new Set(matchedKeywords)).slice(0, 4),
            sharedCount: matchedKeywords.length
          });
        }
      }
    }

    // Determine highest scoring category
    let bestCategory = 'General';
    let highestScore = 0;

    for (const [cat, score] of categoryScores.entries()) {
      if (score > highestScore) {
        highestScore = score;
        bestCategory = cat;
      }
    }

    if (highestScore === 0 || tokens.length === 0) {
      return {
        value: 'General',
        source: 'auto',
        confidence: 0.4,
        reasoning: 'Insufficient distinct keywords; defaulted to General topic'
      };
    }

    const reasoningMeta = categoryReasoning.get(bestCategory);
    const confidence = Math.min(0.98, Number((0.55 + Math.min(highestScore * 0.12, 0.43)).toFixed(2)));

    const reasoning = reasoningMeta.sampleNoteTitle === 'Domain Ontology Knowledge Base'
      ? `Auto-inferred from key terminology overlap [${reasoningMeta.sharedTerms.join(', ')}] matching topic taxonomy`
      : `Matched ${reasoningMeta.sharedCount} conceptual terms [${reasoningMeta.sharedTerms.join(', ')}] aligned with note "${reasoningMeta.sampleNoteTitle}"`;

    return {
      value: bestCategory,
      source: 'auto',
      confidence,
      reasoning
    };
  }

  /**
   * Infer related terms and tags with co-occurrence analysis
   */
  static inferTags({ tokens, keywords, existingTags, otherNotes, inferredCategory }) {
    const existingMap = new Map();
    (existingTags || []).forEach(t => {
      const name = typeof t === 'string' ? t.toLowerCase().trim() : t.name.toLowerCase().trim();
      const source = typeof t === 'string' ? 'auto' : (t.source || 'auto');
      existingMap.set(name, {
        name,
        source,
        confidence: t.confidence ?? (source === 'manual' ? 1.0 : 0.8),
        reasoning: t.reasoning || (source === 'manual' ? 'User added tag' : 'Previously inferred tag')
      });
    });

    const candidateTags = new Map();

    // 1. Top TF-IDF keywords as primary candidate tags
    keywords.slice(0, 5).forEach(kw => {
      if (kw.term.length > 2 && !existingMap.has(kw.term)) {
        candidateTags.set(kw.term, {
          name: kw.term,
          source: 'auto',
          confidence: Number(Math.min(0.95, 0.65 + kw.weight * 0.8).toFixed(2)),
          reasoning: `High TF-IDF term frequency in content (weight: ${kw.weight})`
        });
      }
    });

    // 2. Co-occurrence tag propagation from top similar existing notes
    for (const note of otherNotes) {
      const noteTokens = tokenize(`${note.title} ${note.content}`);
      const similarity = computeJaccardSimilarity(tokens, noteTokens);

      if (similarity > 0.18 && Array.isArray(note.tags)) {
        for (const noteTag of note.tags) {
          const tagName = (typeof noteTag === 'string' ? noteTag : noteTag.name)?.toLowerCase().trim();
          if (tagName && !existingMap.has(tagName) && !candidateTags.has(tagName)) {
            candidateTags.set(tagName, {
              name: tagName,
              source: 'auto',
              confidence: Number(Math.min(0.88, 0.5 + similarity * 0.5).toFixed(2)),
              reasoning: `Contextually suggested from related note "${note.title}" (${Math.round(similarity * 100)}% match)`
            });
          }
        }
      }
    }

    // Merge manual tags first, then auto candidate tags (up to total 7 tags)
    const combined = [...existingMap.values()];
    for (const [name, tagObj] of candidateTags.entries()) {
      if (combined.length >= 7) break;
      combined.push(tagObj);
    }

    return { tags: combined };
  }

  /**
   * Infer relationships between current note and other notes
   */
  static inferRelationships({ currentNote, otherNotes }) {
    const relationships = [];

    for (const other of otherNotes) {
      const otherTokens = tokenize(`${other.title} ${other.content}`);
      const otherTf = getTermFrequencies(otherTokens);

      const cosine = computeCosineSimilarity(currentNote.tf, otherTf);
      const jaccard = computeJaccardSimilarity(currentNote.tokens, otherTokens);
      const combinedScore = (cosine * 0.65) + (jaccard * 0.35);

      const sharedTerms = currentNote.tokens.filter(t => otherTokens.includes(t));
      const uniqueShared = Array.from(new Set(sharedTerms));

      // Relationship Threshold: minimum 0.22 similarity or at least 3 distinct shared tech terms
      if (combinedScore >= 0.22 || uniqueShared.length >= 3) {
        let relationType = 'related_to';
        let reasoning = '';
        const similarityPct = Math.round(combinedScore * 100);

        // Deterministic classification of relationship semantics
        if (combinedScore > 0.75 || (uniqueShared.length >= 6 && Math.abs(currentNote.tokens.length - otherTokens.length) < 5)) {
          relationType = 'synonym_of';
          reasoning = `High reciprocal term convergence (${similarityPct}% similarity). Identical core concepts: [${uniqueShared.slice(0, 4).join(', ')}]`;
        } else if (currentNote.tokens.length > otherTokens.length * 1.5 && otherTokens.every(t => currentNote.tokens.includes(t))) {
          relationType = 'extends';
          reasoning = `Expands upon concepts established in "${other.title}" with additional implementation details`;
        } else if (other.category?.value === currentNote.category?.value && (combinedScore > 0.4 || uniqueShared.length >= 4)) {
          relationType = 'part_of';
          reasoning = `Shares structural domain cluster "${other.category?.value || 'Topic'}" and overlapping terms [${uniqueShared.slice(0, 3).join(', ')}]`;
        } else {
          relationType = 'related_to';
          reasoning = `Semantic overlap of ${uniqueShared.length} shared key concepts [${uniqueShared.slice(0, 4).join(', ')}] (${similarityPct}% match)`;
        }

        relationships.push({
          targetNoteId: String(other._id || other.id),
          targetTitle: other.title || 'Untitled Note',
          relationType,
          source: 'auto',
          similarity: Number(combinedScore.toFixed(3)),
          reasoning
        });
      }
    }

    // Sort relationships by similarity score descending
    return relationships.sort((a, b) => b.similarity - a.similarity).slice(0, 6);
  }
}

