          <button
            onClick={() => onDelete(note._id || note.id)}
            className="p-1.5 rounded-lg text-slate-400 hover:text-red-400 hover:bg-slate-700/60 transition-colors"
            title="Delete Note"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Note Title */}
      <h3 className="text-base font-bold text-slate-100 group-hover:text-indigo-300 line-clamp-1 mb-2">
        {note.title}
      </h3>

      {/* Content Preview */}
      <p className="text-slate-300 text-xs line-clamp-3 leading-relaxed mb-4">
        {note.content}
      </p>

      {/* Semantic Tags with Source Indicators */}
      <div className="flex items-center gap-1.5 flex-wrap mb-4">
        {note.tags && note.tags.slice(0, 4).map((tag, idx) => {
          const tagName = typeof tag === 'string' ? tag : tag.name;
          const tagSource = typeof tag === 'string' ? 'auto' : (tag.source || 'auto');

          return (
            <span 
              key={idx}
              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium ${
                tagSource === 'manual' 
                  ? 'bg-emerald-950/60 text-emerald-300 border border-emerald-800/60' 
                  : 'bg-slate-800/80 text-slate-300 border border-slate-700/60'
              }`}
            >
              <TagIcon className="w-2.5 h-2.5 opacity-60" />
              <span>#{tagName}</span>
              <span className={`text-[9px] px-1 rounded ${
                tagSource === 'manual' ? 'bg-emerald-900/80 text-emerald-200' : 'bg-slate-700/80 text-slate-400'
              }`}>
                {tagSource}
              </span>
            </span>
          );
        })}
        {note.tags && note.tags.length > 4 && (
          <span className="text-[10px] text-slate-400 self-center">
            +{note.tags.length - 4} more
          </span>
        )}
      </div>

      {/* Footer Info & Reasoning Snippet */}
      <div className="pt-3 border-t border-slate-800/80 flex items-center justify-between text-[11px] text-slate-400">
        <div className="flex items-center gap-1">
          <Clock className="w-3 h-3 text-slate-400" />
          <span>{dateStr}</span>
        </div>

        <button 
          onClick={() => onSelect(note)}
          className="inline-flex items-center gap-1 text-indigo-400 hover:text-indigo-300 font-semibold group"
        >
          <Cpu className="w-3 h-3 text-indigo-400" />
          <span>Inspect Semantics</span>
          <ArrowUpRight className="w-3 h-3 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Check, 
  X, 
  Plus, 
  Link2, 
  BrainCircuit, 
  Tag as TagIcon, 
  AlertCircle, 
  CheckCircle2, 
  HelpCircle,
  Cpu
} from 'lucide-react';
import { api } from '../services/api';

const PRESET_CATEGORIES = [
  'Frontend Architecture',
  'Backend & APIs',
  'Database & Storage',
  'Cloud & DevOps',
  'Machine Learning & AI',
  'Product & Workflow',
  'Security & Auth',
  'General'
];

export function NoteForm({ initialNote, onSave, onCancel }) {
  const [title, setTitle] = useState(initialNote?.title || '');
  const [content, setContent] = useState(initialNote?.content || '');

  // Category state with provenance
  const [category, setCategory] = useState(
    initialNote?.category?.value || 'General'
  );
  const [categorySource, setCategorySource] = useState(
    initialNote?.category?.source || 'auto'
  );
  const [categoryConfidence, setCategoryConfidence] = useState(
    initialNote?.category?.confidence || 0.75
  );
  const [categoryReasoning, setCategoryReasoning] = useState(
    initialNote?.category?.reasoning || ''
  );

  // Tags state
  const [tags, setTags] = useState(
    initialNote?.tags || []
  );
  const [tagInput, setTagInput] = useState('');

  // Live semantic analysis results
  const [liveAnalysis, setLiveAnalysis] = useState(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState('');
  const debounceTimerRef = useRef(null);

  // Trigger live semantic analysis on title/content changes
  useEffect(() => {
    if (!title.trim() && !content.trim()) {
      setLiveAnalysis(null);
      return;
    }

    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);

    debounceTimerRef.current = setTimeout(async () => {
      try {
        setIsAnalyzing(true);
        const res = await api.analyzeSemantic({
          title,
          content,
          category: { value: category, source: categorySource },
          tags,
          targetNoteId: initialNote?._id || initialNote?.id
        });

        if (res.success && res.analysis) {
          setLiveAnalysis(res.analysis);

          // If category is still 'auto', automatically adopt the highest scoring inferred category
          if (categorySource === 'auto' && res.analysis.category) {
            setCategory(res.analysis.category.value);
            setCategoryConfidence(res.analysis.category.confidence);
            setCategoryReasoning(res.analysis.category.reasoning);
          }
        }
      } catch (err) {
        console.error('Semantic preview error:', err);
      } finally {
        setIsAnalyzing(false);
      }
    }, 400);

    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [title, content]);

  // Handle manual category change
  const handleCategorySelect = (newCategory) => {
    setCategory(newCategory);
    setCategorySource('manual');
    setCategoryConfidence(1.0);
    setCategoryReasoning('Manually selected by user during editing');
  };

  // Revert category to auto suggestion
  const handleRevertCategoryToAuto = () => {
    if (liveAnalysis?.category) {
      setCategory(liveAnalysis.category.value);
      setCategorySource('auto');
      setCategoryConfidence(liveAnalysis.category.confidence);
      setCategoryReasoning(liveAnalysis.category.reasoning);
    } else {
      setCategorySource('auto');
    }
  };

  // Add tag manually
  const handleAddTag = (e) => {
    e?.preventDefault();
    const clean = tagInput.trim().toLowerCase().replace(/^#/, '');
    if (!clean) return;

    if (!tags.some(t => (typeof t === 'string' ? t : t.name).toLowerCase() === clean)) {
      setTags([
        ...tags,
        {
          name: clean,
          source: 'manual',
          confidence: 1.0,
          reasoning: 'Explicitly added by user'
        }
      ]);
    }
    setTagInput('');
  };

  // Accept a live suggested tag
  const handleAcceptSuggestedTag = (suggestedTag) => {
    const tagName = suggestedTag.name.toLowerCase();
    if (!tags.some(t => (typeof t === 'string' ? t : t.name).toLowerCase() === tagName)) {
      setTags([
        ...tags,
        {
          ...suggestedTag,
          source: 'manual', // accepting marks it as user confirmed
          reasoning: `Accepted suggestion: ${suggestedTag.reasoning || 'relevant keyword'}`
        }
      ]);
    }
  };

  // Remove tag
  const handleRemoveTag = (tagName) => {
    setTags(tags.filter(t => (typeof t === 'string' ? t : t.name) !== tagName));
  };

  // Toggle tag source between auto & manual
  const handleToggleTagSource = (tagName) => {
    setTags(tags.map(t => {
      const name = typeof t === 'string' ? t : t.name;
      if (name === tagName) {
        const currentSource = typeof t === 'string' ? 'auto' : t.source;
        const newSource = currentSource === 'auto' ? 'manual' : 'auto';
        return {
          name,
          source: newSource,
          confidence: newSource === 'manual' ? 1.0 : (t.confidence || 0.8),
          reasoning: newSource === 'manual' ? 'Manually locked by user' : 'Reverted to auto inference'
        };
      }
      return t;
    }));
  };

  // Submit Note
  const handleSubmit = (e) => {
    e.preventDefault();
    if (!title.trim() || !content.trim()) {
      setError('Title and content are required.');
      return;
    }

    const payload = {
      title: title.trim(),
      content: content.trim(),
      category: {
        value: category,
        source: categorySource,
        confidence: categoryConfidence,
        reasoning: categoryReasoning
      },
      tags: tags.map(t => typeof t === 'string' ? { name: t, source: 'manual', confidence: 1.0 } : t),
      relationships: liveAnalysis?.relationships || initialNote?.relationships || []
    };

    onSave(payload);
  };

  return (
    <div className="bg-slate-900 border border-slate-700/80 rounded-2xl p-6 shadow-2xl">
      {/* Form Header */}
      <div className="flex items-center justify-between pb-4 mb-5 border-b border-slate-800">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-indigo-500/10 border border-indigo-500/30 text-indigo-400">
            <BrainCircuit className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-100">
              {initialNote ? 'Edit Note & Semantic Properties' : 'Create Note with Auto-Classification'}
            </h2>
            <p className="text-xs text-slate-400">
              Semantic engine infers topic, tags, and conceptual relationships in real-time
            </p>
          </div>
        </div>

        {isAnalyzing && (
          <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/30 text-indigo-400 text-xs animate-pulse">
            <Cpu className="w-3.5 h-3.5 animate-spin" />
            <span>Analyzing Context...</span>
          </div>
        )}
      </div>

      {error && (
        <div className="mb-4 p-3 rounded-xl bg-red-500/10 border border-red-500/30 text-red-300 text-xs flex items-center gap-2">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-5">
        {/* Title Input */}
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5">
            Note Title
          </label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="e.g. Building Resilient Microservices with Express"
            className="w-full px-4 py-2.5 rounded-xl bg-slate-800/80 border border-slate-700 text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-sm"
          />
        </div>

        {/* Content Input */}
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5">
            Content & Details
          </label>
          <textarea
            rows={4}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Describe technical implementation, patterns, keywords, and notes..."
            className="w-full px-4 py-3 rounded-xl bg-slate-800/80 border border-slate-700 text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-sm leading-relaxed"
          />
        </div>

        {/* --- LIVE AUTO-CLASSIFICATION & SEMANTIC CONTROLS --- */}
        <div className="p-4 rounded-xl bg-slate-950/60 border border-slate-800 space-y-4">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold uppercase tracking-wider text-indigo-400 flex items-center gap-1.5">
              <Sparkles className="w-3.5 h-3.5" />
              Semantic Organization State
            </span>
            <span className="text-[11px] text-slate-400">
              Interactive suggestion & override controls
            </span>
          </div>

          {/* 1. Category Field with Auto/Manual Provenance */}
          <div className="space-y-2">
            <div className="flex items-center justify-between text-xs">
              <span className="text-slate-300 font-medium">Assigned Category:</span>
              <div className="flex items-center gap-2">
                <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                  categorySource === 'auto' 
                    ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30' 
                    : 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
                }`}>
                  {categorySource === 'auto' ? <Sparkles className="w-2.5 h-2.5" /> : <CheckCircle2 className="w-2.5 h-2.5" />}
                  Source: {categorySource}
                </span>

                {categorySource === 'manual' && (
                  <button
                    type="button"
                    onClick={handleRevertCategoryToAuto}
                    className="text-[11px] text-slate-400 hover:text-indigo-300 underline"
                  >
                    Reset to auto
                  </button>
                )}
              </div>
            </div>

            {/* Category Dropdown & Quick Select */}
            <div className="flex items-center gap-2">
              <select
                value={category}
                onChange={(e) => handleCategorySelect(e.target.value)}
                className="flex-1 px-3 py-2 rounded-lg bg-slate-800 border border-slate-700 text-slate-100 text-xs focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              >
                {PRESET_CATEGORIES.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>

            {/* Auto Inference Reasoning Banner */}
            {categoryReasoning && (
              <div className="p-2.5 rounded-lg bg-indigo-950/30 border border-indigo-900/50 text-[11px] text-indigo-300 flex items-start gap-2">
                <BrainCircuit className="w-3.5 h-3.5 text-indigo-400 flex-shrink-0 mt-0.5" />
                <div>
                  <span className="font-semibold text-indigo-200">
                    {categorySource === 'auto' ? `Confidence ${Math.round(categoryConfidence * 100)}%:` : 'Explanation:'}
                  </span>{' '}
                  {categoryReasoning}
                </div>
              </div>
            )}
          </div>

          {/* 2. Tags Section (Active Tags + Live Inferred Suggestions) */}
          <div className="space-y-2 pt-2 border-t border-slate-800/80">
            <div className="flex items-center justify-between text-xs">
              <span className="text-slate-300 font-medium">Attached Tags:</span>
              <span className="text-[10px] text-slate-400">Click badge to toggle [auto/manual]</span>
            </div>

            {/* Active Tags list */}
            <div className="flex items-center gap-1.5 flex-wrap min-h-[30px]">
              {tags.map((tag, idx) => {
                const tagName = typeof tag === 'string' ? tag : tag.name;
                const tagSource = typeof tag === 'string' ? 'manual' : (tag.source || 'auto');

                return (
                  <span
                    key={idx}
                    className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium border transition-colors ${
                      tagSource === 'manual'
                        ? 'bg-emerald-950/50 text-emerald-300 border-emerald-700/60'
                        : 'bg-blue-950/50 text-blue-300 border-blue-700/60'
                    }`}
                  >
                    <TagIcon className="w-3 h-3 opacity-70" />
                    <span>#{tagName}</span>
                    <button
                      type="button"
                      onClick={() => handleToggleTagSource(tagName)}
                      className={`text-[9px] px-1 rounded font-mono ${
                        tagSource === 'manual' ? 'bg-emerald-800/80 text-emerald-100' : 'bg-blue-800/80 text-blue-100'
                      }`}
                      title="Click to toggle auto/manual state"
                    >
                      {tagSource}
                    </button>
                    <button
                      type="button"
                      onClick={() => handleRemoveTag(tagName)}
                      className="text-slate-400 hover:text-red-400 transition-colors ml-0.5"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                );
              })}

              {tags.length === 0 && (
                <span className="text-xs text-slate-400 italic">No tags attached yet</span>
              )}
            </div>

            {/* Add Custom Tag Input */}
            <div className="flex items-center gap-2 pt-1">
              <input
                type="text"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleAddTag(e); }}
                placeholder="Add custom tag (press Enter)..."
                className="flex-1 px-3 py-1.5 rounded-lg bg-slate-800 border border-slate-700 text-slate-100 placeholder-slate-500 text-xs focus:ring-1 focus:ring-indigo-500 focus:outline-none"
              />
              <button
                type="button"
                onClick={handleAddTag}
                className="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-semibold flex items-center gap-1 border border-slate-700"
              >
                <Plus className="w-3 h-3" />
                Add Tag
              </button>
            </div>

            {/* Inferred Candidate Tags Suggestions */}
            {liveAnalysis?.tags && (
              <div className="pt-2">
                <div className="text-[11px] font-semibold text-slate-400 mb-1 flex items-center gap-1">
                  <Sparkles className="w-3 h-3 text-indigo-400" />
                  <span>Suggested from Context & TF-IDF (Click to accept):</span>
                </div>
                <div className="flex items-center gap-1.5 flex-wrap">
                  {liveAnalysis.tags
                    .filter(st => !tags.some(t => (typeof t === 'string' ? t : t.name) === st.name))
                    .map((st, idx) => (
                      <button
                        key={idx}
                        type="button"
                        onClick={() => handleAcceptSuggestedTag(st)}
                        className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium bg-indigo-950/40 text-indigo-300 border border-indigo-800/50 hover:bg-indigo-900/60 hover:text-indigo-200 transition-colors group"
                        title={st.reasoning}
                      >
                        <Plus className="w-2.5 h-2.5 text-indigo-400 group-hover:scale-125 transition-transform" />
                        <span>+{st.name}</span>
                        <span className="text-[9px] text-indigo-400/80 font-mono">
                          {Math.round((st.confidence || 0.8) * 100)}%
                        </span>
                      </button>
                    ))}
                </div>
              </div>
            )}
          </div>

          {/* 3. Live Relationships Preview */}
          {liveAnalysis?.relationships && liveAnalysis.relationships.length > 0 && (
            <div className="space-y-1.5 pt-2 border-t border-slate-800/80">
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-300 font-medium flex items-center gap-1.5">
                  <Link2 className="w-3.5 h-3.5 text-purple-400" />
                  Inferred Relationships ({liveAnalysis.relationships.length}):
                </span>
                <span className="text-[10px] text-slate-400">Auto-linked based on semantic similarity</span>
              </div>

              <div className="grid grid-cols-1 gap-1.5 max-h-36 overflow-y-auto pr-1">
                {liveAnalysis.relationships.map((rel, idx) => (
                  <div 
                    key={idx}
                    className="p-2 rounded-lg bg-slate-900 border border-purple-900/30 flex items-center justify-between text-xs"
                  >
                    <div className="flex items-center gap-2 overflow-hidden">
                      <span className="px-1.5 py-0.5 rounded text-[10px] font-mono font-bold bg-purple-950 text-purple-300 border border-purple-800">
                        {rel.relationType}
                      </span>
                      <span className="text-slate-200 truncate font-medium">
                        "{rel.targetTitle}"
                      </span>
                    </div>
                    <span className="text-[10px] text-purple-300 font-mono font-bold ml-2">
                      {Math.round(rel.similarity * 100)}% match
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Buttons */}
        <div className="flex items-center justify-end gap-3 pt-2">
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 rounded-xl text-slate-400 hover:text-slate-200 hover:bg-slate-800 text-xs font-semibold transition-colors"
          >
            Cancel
          </button>
          <button
            type="submit"
            className="px-5 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-lg shadow-indigo-600/30 flex items-center gap-2 transition-all"
          >
            <Check className="w-4 h-4" />
            {initialNote ? 'Update Note' : 'Create Note'}
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Sparkles, 
  CheckCircle2, 
  BrainCircuit, 
  Link2, 
  Tag as TagIcon, 
  History, 
  Code, 
  X, 
  ArrowRight, 
  Check, 
  Plus, 
  Trash2, 
  AlertCircle,
  HelpCircle,
  TrendingUp,
  Cpu,
  Layers
} from 'lucide-react';

const PRESET_CATEGORIES = [
  'Frontend Architecture',
  'Backend & APIs',
  'Database & Storage',
  'Cloud & DevOps',
  'Machine Learning & AI',
  'Product & Workflow',
  'Security & Auth',
  'General'
];

const RELATION_TYPES = [
  { value: 'related_to', label: 'Related To (Topic Overlap)', color: 'bg-purple-900/50 text-purple-300 border-purple-700' },
  { value: 'part_of', label: 'Part Of (Hierarchical Sub-Topic)', color: 'bg-amber-900/50 text-amber-300 border-amber-700' },
  { value: 'synonym_of', label: 'Synonym Of (Equivalent Concept)', color: 'bg-pink-900/50 text-pink-300 border-pink-700' },
  { value: 'extends', label: 'Extends (Elaboration / Sequel)', color: 'bg-cyan-900/50 text-cyan-300 border-cyan-700' }
];

export function SemanticInspector({ note, allNotes, onClose, onUpdateNote }) {
  const [activeTab, setActiveTab] = useState('inspector'); // 'inspector' | 'history' | 'raw_json'
  const [editingCategory, setEditingCategory] = useState(false);
  const [customCategory, setCustomCategory] = useState(note?.category?.value || 'General');

  const [newTagInput, setNewTagInput] = useState('');
  const [newRelTargetId, setNewRelTargetId] = useState('');
  const [newRelType, setNewRelType] = useState('related_to');

  if (!note) return null;

  const categoryValue = note.category?.value || 'General';
  const categorySource = note.category?.source || 'auto';
  const categoryConfidence = note.category?.confidence ?? 0.75;
  const categoryReasoning = note.category?.reasoning || 'No explicit reasoning available';

  // --- Category Actions ---
  const handleAcceptCategory = () => {
    onUpdateNote(note._id || note.id, {
      ...note,
      category: {
        value: categoryValue,
        source: 'manual',
        confidence: 1.0,
        reasoning: 'Accepted auto-suggestion and locked by user'
      }
    });
  };

  const handleOverrideCategory = () => {
    if (!customCategory.trim()) return;
    onUpdateNote(note._id || note.id, {
      ...note,
      category: {
        value: customCategory.trim(),
        source: 'manual',
        confidence: 1.0,
        reasoning: 'Manually assigned by user'
      }
    });
    setEditingCategory(false);
  };

  const handleResetCategoryToAuto = () => {
    onUpdateNote(note._id || note.id, {
      ...note,
      category: {
        value: categoryValue,
        source: 'auto',
        confidence: categoryConfidence,
        reasoning: 'Reverted back to system automated classification'
      }
    });
  };

  // --- Tag Actions ---
  const handleToggleTagSource = (tagName) => {
    const updatedTags = (note.tags || []).map(t => {
      const name = typeof t === 'string' ? t : t.name;
      if (name === tagName) {
        const currentSource = typeof t === 'string' ? 'auto' : t.source;
        const newSource = currentSource === 'auto' ? 'manual' : 'auto';
        return {
          name,
          source: newSource,
          confidence: newSource === 'manual' ? 1.0 : (t.confidence || 0.8),
          reasoning: newSource === 'manual' ? 'Manually accepted & verified by user' : 'Reverted to auto inference'
        };
      }
      return typeof t === 'string' ? { name: t, source: 'manual', confidence: 1.0 } : t;
    });

    onUpdateNote(note._id || note.id, { ...note, tags: updatedTags });
  };

  const handleAddManualTag = (e) => {
    e?.preventDefault();
    const clean = newTagInput.trim().toLowerCase().replace(/^#/, '');
    if (!clean) return;

    const existingTags = note.tags || [];
    if (!existingTags.some(t => (typeof t === 'string' ? t : t.name).toLowerCase() === clean)) {
      const updatedTags = [
        ...existingTags,
        {
          name: clean,
          source: 'manual',
          confidence: 1.0,
          reasoning: 'Added manually via Semantic Inspector'
        }
      ];
      onUpdateNote(note._id || note.id, { ...note, tags: updatedTags });
    }
    setNewTagInput('');
  };

  const handleRemoveTag = (tagName) => {
    const updatedTags = (note.tags || []).filter(t => (typeof t === 'string' ? t : t.name) !== tagName);
    onUpdateNote(note._id || note.id, { ...note, tags: updatedTags });
  };

  // --- Relationship Actions ---
  const handleToggleRelSource = (targetNoteId) => {
    const updatedRels = (note.relationships || []).map(rel => {
      if (String(rel.targetNoteId) === String(targetNoteId)) {
        const newSource = rel.source === 'auto' ? 'manual' : 'auto';
        return {
          ...rel,
          source: newSource,
          reasoning: newSource === 'manual' ? 'Manually confirmed relationship' : rel.reasoning
        };
      }
      return rel;
    });
    onUpdateNote(note._id || note.id, { ...note, relationships: updatedRels });
  };

  const handleUpdateRelType = (targetNoteId, newType) => {
    const updatedRels = (note.relationships || []).map(rel => {
      if (String(rel.targetNoteId) === String(targetNoteId)) {
        return {
          ...rel,
          relationType: newType,
          source: 'manual',
          reasoning: `Manually changed relation type to ${newType}`
        };
      }
      return rel;
    });
    onUpdateNote(note._id || note.id, { ...note, relationships: updatedRels });
  };

  const handleRemoveRelationship = (targetNoteId) => {
    const updatedRels = (note.relationships || []).filter(r => String(r.targetNoteId) !== String(targetNoteId));
    onUpdateNote(note._id || note.id, { ...note, relationships: updatedRels });
  };

  const handleAddRelationship = (e) => {
    e?.preventDefault();
    if (!newRelTargetId) return;

    const target = allNotes.find(n => String(n._id || n.id) === String(newRelTargetId));
    if (!target) return;

    const existingRels = note.relationships || [];
    if (!existingRels.some(r => String(r.targetNoteId) === String(newRelTargetId))) {
      const updatedRels = [
        ...existingRels,
        {
          targetNoteId: String(target._id || target.id),
          targetTitle: target.title,
          relationType: newRelType,
          source: 'manual',
          similarity: 1.0,
          reasoning: 'Explicitly linked by user in Semantic Inspector'
        }
      ];
      onUpdateNote(note._id || note.id, { ...note, relationships: updatedRels });
    }
    setNewRelTargetId('');
  };

  // Other notes available for linking
  const linkableNotes = (allNotes || []).filter(n => 
    String(n._id || n.id) !== String(note._id || note.id) &&
    !(note.relationships || []).some(r => String(r.targetNoteId) === String(n._id || n.id))
  );

  return (
    <div className="fixed inset-y-0 right-0 w-full md:w-[480px] bg-slate-900 border-l border-slate-700/80 shadow-2xl z-50 flex flex-col backdrop-blur-xl">
      {/* Header */}
      <div className="p-5 border-b border-slate-800 flex items-center justify-between bg-slate-900/90">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-indigo-500/10 border border-indigo-500/30 text-indigo-400">
            <Cpu className="w-5 h-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-sm font-bold text-slate-100">Semantic Inspector</h2>
              <span className="px-1.5 py-0.5 rounded bg-indigo-950 text-indigo-300 border border-indigo-800 text-[10px] font-mono">
                Live State
              </span>
            </div>
            <p className="text-[11px] text-slate-400 truncate max-w-[260px]">
              {note.title}
            </p>
          </div>
        </div>

        <button
          onClick={onClose}
          className="p-1.5 rounded-lg text-slate-400 hover:text-slate-200 hover:bg-slate-800 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Tabs */}
      <div className="flex items-center px-5 border-b border-slate-800 bg-slate-950/40 text-xs font-semibold">
        <button
          onClick={() => setActiveTab('inspector')}
          className={`py-3 px-3 border-b-2 flex items-center gap-1.5 transition-colors ${
            activeTab === 'inspector' 
              ? 'border-indigo-500 text-indigo-400' 
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <BrainCircuit className="w-3.5 h-3.5" />
          Semantic State
        </button>

        <button
          onClick={() => setActiveTab('history')}
          className={`py-3 px-3 border-b-2 flex items-center gap-1.5 transition-colors ${
            activeTab === 'history' 
              ? 'border-indigo-500 text-indigo-400' 
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <History className="w-3.5 h-3.5" />
          Audit Trail ({note.semanticHistory?.length || 0})
        </button>

        <button
          onClick={() => setActiveTab('raw_json')}
          className={`py-3 px-3 border-b-2 flex items-center gap-1.5 transition-colors ${
            activeTab === 'raw_json' 
              ? 'border-indigo-500 text-indigo-400' 
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Code className="w-3.5 h-3.5" />
          Raw JSON (Provable State)
        </button>
      </div>

      {/* Content Area */}
