                <span className="text-xs font-bold uppercase tracking-wider text-slate-400 flex items-center gap-1">
                  <Link2 className="w-3.5 h-3.5 text-purple-400" />
                  Conceptual Relationships ({note.relationships?.length || 0})
                </span>
                <span className="text-[10px] text-purple-400">
                  Multi-Type Graph Links
                </span>
              </div>

              {/* Relationship items */}
              <div className="space-y-2.5">
                {note.relationships && note.relationships.length > 0 ? (
                  note.relationships.map((rel, idx) => {
                    const relTypeInfo = RELATION_TYPES.find(r => r.value === rel.relationType) || RELATION_TYPES[0];

                    return (
                      <div 
                        key={idx}
                        className="p-3 rounded-lg bg-slate-900 border border-slate-800 space-y-2 text-xs"
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div>
                            <div className="font-semibold text-slate-200 line-clamp-1">
                              "{rel.targetTitle || 'Connected Note'}"
                            </div>
                            <div className="flex items-center gap-2 mt-1">
                              <select
                                value={rel.relationType}
                                onChange={(e) => handleUpdateRelType(rel.targetNoteId, e.target.value)}
                                className="px-2 py-0.5 rounded bg-slate-800 border border-slate-700 text-[11px] text-purple-300 font-mono focus:outline-none"
                              >
                                {RELATION_TYPES.map(rt => (
                                  <option key={rt.value} value={rt.value}>{rt.value}</option>
                                ))}
                              </select>

                              <button
                                onClick={() => handleToggleRelSource(rel.targetNoteId)}
                                className={`text-[10px] px-1.5 py-0.5 rounded font-mono font-bold uppercase ${
                                  rel.source === 'manual'
                                    ? 'bg-emerald-950 text-emerald-300 border border-emerald-800'
                                    : 'bg-blue-950 text-blue-300 border border-blue-800'
                                }`}
                              >
                                {rel.source}
                              </button>
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            <span className="text-[11px] font-mono font-bold text-purple-400">
                              {Math.round((rel.similarity || 0) * 100)}% match
                            </span>
                            <button
                              onClick={() => handleRemoveRelationship(rel.targetNoteId)}
