              {/* Add Manual Link */}
              {linkableNotes.length > 0 && (
                <form onSubmit={handleAddRelationship} className="space-y-2 pt-2 border-t border-slate-800/80">
                  <div className="text-[11px] font-semibold text-slate-400">Add Manual Conceptual Link:</div>
                  <div className="grid grid-cols-2 gap-2">
                    <select
                      value={newRelTargetId}
                      onChange={(e) => setNewRelTargetId(e.target.value)}
                      className="w-full px-2.5 py-1.5 rounded-lg bg-slate-800 border border-slate-700 text-slate-100 text-xs"
                    >
                      <option value="">Select target note...</option>
                      {linkableNotes.map(ln => (
                        <option key={ln._id || ln.id} value={ln._id || ln.id}>
                          {ln.title}
                        </option>
                      ))}
